def parallel_market(connection: sqlite3.Connection, action: str, payload: dict) -> dict:
    state = current(connection)
    if not state.get('started'):
        raise ValueError('CAREER_NOT_STARTED')
    career_id = int(payload.get('career_id') or state['careerId'])
    service = ManagerService(connection)
    if action == 'parallel_snapshot':
        return service.parallel_league_snapshot(career_id, int(payload.get('season_number', 1)))
    if action == 'parallel_result':
        return service.record_parallel_result(career_id, int(payload.get('fixture_id')), int(payload.get('home_goals')), int(payload.get('away_goals')))
    if action == 'parallel_close':
        return service.close_parallel_season(career_id, int(payload.get('season_number', 1)))
    raise ValueError('PARALLEL_LEAGUE_ACTION_INVALID')


def play_controlled_match(connection: sqlite3.Connection, payload: dict) -> dict:
    club_id = current_club_id(connection)
    match_id = int(payload.get("match_id") or 0)
    if match_id <= 0:
        raise ValueError("MATCH_ID_REQUIRED")
    match = connection.execute(
        "SELECT match_id,competition_id,home_club_id,away_club_id,status FROM matches WHERE match_id=?",
        (match_id,),
    ).fetchone()
    if match is None:
        raise ValueError("MATCH_NOT_FOUND")
    if int(match["home_club_id"]) != club_id and int(match["away_club_id"]) != club_id:
        raise ValueError("CONTROLLED_MATCH_REQUIRED")
    if match["status"] != "SCHEDULED":
        raise ValueError("MATCH_NOT_SCHEDULED")
    seed = payload.get("seed")
    result = CompetitionService(connection).play(match_id, seed=int(seed) if seed is not None else None, managed_transaction=False)
    connection.commit()
    return {
        "status": "PLAYED",
        "match_id": result.match_id,
        "controlled_club_id": club_id,
        "home_club_id": int(match["home_club_id"]),
        "away_club_id": int(match["away_club_id"]),
        "home_goals": result.home_goals,
        "away_goals": result.away_goals,
        "seed": result.seed,
    }


